SEGS = lambda id,lbl,items: '<div class="ctl"><span class="lbl">%s</span><div class="seg" id="%s" role="group" aria-label="%s">' % (lbl,id,lbl) + ''.join('<button type="button" data-k="%s" aria-pressed="%s">%s</button>' % (k,'true' if i==0 else 'false',t) for i,(k,t) in enumerate(items)) + '</div></div>'

mod('selection','Natural selection',
 'Populations change because individuals that happen to fit their environment better leave more offspring. Nothing in the process looks ahead.',
 ['Natural selection needs four things: <b>variation</b> in a trait, the trait is <b>heritable</b>, more offspring are produced than can survive, and individuals with some trait values <b>survive and reproduce more</b> (higher <b>fitness</b>). Over generations the alleles associated with those traits become more common. <b>Individuals do not evolve</b>; populations do. Selection acts on phenotypes, but what changes is allele frequency.',
  'The effect on a trait depends on which phenotypes are favored. <b>Directional selection</b> favors one extreme and shifts the mean (antibiotic resistance, finch beak depth in drought). <b>Stabilizing selection</b> favors the middle and narrows the spread (human birth weight). <b>Disruptive selection</b> favors both extremes and can split a population in two (seedcracker finch beaks). Other forces: <b>sexual selection</b> (traits that help win mates) and <b>artificial selection</b> (humans choose who breeds).'],
 ('organisms change because they need to','that selection acts on existing variation, and only populations change','how traits change across generations and why resistance evolves','fitness, heritability and the three modes of selection'),
 [('fitness = reproductive success','survival and number of offspring'),('directional: mean shifts','stabilizing: variation narrows; disruptive: two peaks'),('response to selection depends on heritability','needs genetic variation'),('p′ = p·w₁ / (p·w₁ + q·w₂)','allele frequency after selection (model)')],
 [lab('ns-lab','Selection on a trait',canvas='ns-canvas',aria='A histogram of a trait in a population. Each generation the favored individuals reproduce, and the distribution changes.',
   seg=('ns-mode','Selection',[('dir','directional (favors large)'),('sta','stabilizing'),('dis','disruptive')]),
   ctl=[('ns-s','Selection strength',1,10,1,5)],
   pre='<div class="row"><button type="button" class="btn primary" id="ns-next">Next generation</button><button type="button" class="btn" id="ns-ten">+10 generations</button><button type="button" class="btn" id="ns-reset">Start over</button></div>',
   out=[('ns-gen','generation','x'),('ns-mean','mean of the trait','a'),('ns-sd','spread (SD)','v')],own=True),
  lab('ns-lab2','Antibiotic resistance',canvas='ns-canvas2',aria='A graph of the proportion of bacteria that are resistant over generations in the presence of an antibiotic.',
   ctl=[('ns-p0','Starting resistant fraction',.0001,.1,.0001,.001),('ns-sc','Selection against sensitive cells',.05,.9,.01,.3)],
   out=[('ns-g50','generations until half are resistant','x'),('ns-g99','generations until 99% are resistant','a')],own=True)],
 [('Choose directional selection and press +10 generations. What happens to the mean? <button type="button" class="btn link" data-show=\'' + show(["click","#ns-mode [data-k=dir]"],["click","#ns-reset"],["click","#ns-ten"]) + '\'>Set it up for me</button>','','The mean shifts toward the favored extreme and the distribution keeps its shape.'),
  ('Choose disruptive selection and run 10 generations. <button type="button" class="btn link" data-show=\'' + show(["click","#ns-mode [data-k=dis]"],["click","#ns-reset"],["click","#ns-ten"]) + '\'>Set it up for me</button>','','Two peaks appear at the extremes and the middle becomes rare. The mean may stay about the same while the spread increases.'),
  ('In the resistance lab, make the antibiotic stronger (raise the selection). <button type="button" class="btn link" data-show=\'' + show(["#ns-sc",.8]) + '\'>Set it up for me</button>','','Resistance spreads in fewer generations: stronger selection means a bigger fitness difference.')],
 ('Before an antibiotic is used, 1 in 10,000 bacteria carry a resistance allele. After exposure, most sensitive bacteria die and survivors multiply. Explain how the population becomes resistant without any bacterium "deciding" to.',[
  '<b>Variation.</b> Resistance already exists in a few cells (from mutation).',
  '<b>Selection.</b> The antibiotic kills sensitive cells but not resistant ones, so resistant cells have higher fitness.',
  '<b>Heredity.</b> Survivors pass the allele to their offspring.',
  '<b>Result.</b> The frequency of the resistant allele rises each generation. The change is in the population, not in individual cells.']),
 ['Saying individuals evolve or adapt during their lifetime.','Saying organisms change "because they need to".','Treating fitness as strength instead of reproductive success.','Forgetting that selection needs heritable variation.','Saying mutations are caused by the environment to help the organism (they arise randomly; the environment selects).'],
 ('Writing the evolution explanation',['Use the four steps: variation, heritability, differential survival and reproduction, change in allele frequency over generations. Name the selective pressure and the favored phenotype, and say which mode of selection applies.']),
 [('A population of birds has beak depths that cluster around the mean. Both very small and very large beaks have lower survival. This is',['stabilizing selection','directional selection','disruptive selection','genetic drift'],0,'Intermediate phenotypes are favored, and the extremes are selected against.')])

mod('hw','Hardy–Weinberg equilibrium',
 'If nothing is changing allele frequencies, genotype frequencies follow a simple pattern. Departures from that pattern tell you evolution is happening.',
 ['For a gene with two alleles, let <b>p</b> be the frequency of the dominant allele and <b>q</b> the frequency of the recessive allele: <b>p + q = 1</b>. If the population is in <b>Hardy–Weinberg equilibrium</b>, the genotype frequencies after random mating are <b>p² + 2pq + q² = 1</b> (p² homozygous dominant, 2pq heterozygous, q² homozygous recessive). Allele frequencies do not change from generation to generation.',
  'Equilibrium needs five conditions: <b>very large population</b> (no drift), <b>random mating</b>, <b>no mutation</b>, <b>no gene flow</b>, and <b>no natural selection</b>. Real populations violate them, so the equation is a null model: if observed genotype frequencies differ from expected (tested with chi-square), at least one condition is violated. Typical use: given the frequency of the recessive phenotype (q²), find q = √(q²), then p = 1 − q and the carrier frequency 2pq.'],
 ('evolution was only about traits changing','that evolution can be measured as a change in allele frequencies and compared with a baseline','how to calculate carrier frequencies and test for evolution','p + q = 1, p² + 2pq + q² = 1 and the five conditions'),
 [('p + q = 1','alleles'),('p² + 2pq + q² = 1','genotypes'),('q = √(frequency of recessive phenotype)','if equilibrium'),('conditions: large, random mating, no mutation, no gene flow, no selection','null model')],
 [lab('hw-lab','Genotype frequencies from q',canvas='hw-canvas',aria='Bars showing the expected frequencies of the three genotypes for the chosen allele frequency and a population count.',
   ctl=[('hw-q','Frequency of the recessive allele (q)',0,1,.01,.3),('hw-n','Population size',100,10000,100,1000)],
   out=[('hw-p','p (dominant allele)','x'),('hw-gt','AA : Aa : aa','a'),('hw-car','carriers (Aa)','v'),('hw-aa','individuals with the recessive phenotype','')],own=True),
  lab('hw-lab2','Is this population in equilibrium?',canvas='hw-canvas2',aria='Observed and expected genotype counts for the chosen population and a chi-square result.',
   ctl=[('hw-o1','Observed AA',0,500,1,360),('hw-o2','Observed Aa',0,500,1,480),('hw-o3','Observed aa',0,500,1,160)],
   out=[('hw-f','allele frequencies','x'),('hw-chi','χ² (df = 1)','a'),('hw-v','verdict (critical value 3.84)','v')],own=True)],
 [('Set q = 0.2. What is the carrier frequency? <button type="button" class="btn link" data-show=\'' + show(["#hw-q",.2]) + '\'>Set it up for me</button>','','p = 0.8; 2pq = 2(0.8)(0.2) = 0.32, so 32% of the population are carriers; only 4% (q²) show the recessive phenotype.'),
  ('Observed counts 360, 480, 160 are what Hardy–Weinberg predicts for q = 0.4 (1000 individuals). Now try 500, 200, 300. <button type="button" class="btn link" data-show=\'' + show(["#hw-o1",500],["#hw-o2",200],["#hw-o3",300]) + '\'>Set it up for me</button>','','Far too few heterozygotes: χ² is large, so the population is not in equilibrium (for example, inbreeding or selection).')],
 ('In a population in Hardy–Weinberg equilibrium, 4% of people show a recessive trait. What is the frequency of carriers?',[
  '<b>q².</b> q² = 0.04, so q = √0.04 = 0.2.',
  '<b>p.</b> p = 1 − 0.2 = 0.8.',
  '<b>Carriers.</b> 2pq = 2 × 0.8 × 0.2 = 0.32.',
  '<b>Answer.</b> 32% carry the allele without showing the trait.']),
 ['Setting q² = frequency of the recessive allele (q² is the frequency of the genotype, q is the allele).','Using the carrier frequency as q.','Forgetting that the equation only applies when the five conditions hold.','Saying 2pq is homozygous.','Adding p and q to different totals (counts instead of frequencies).'],
 ('Common question types',['(1) Given q², find q, p, 2pq. (2) Given genotype counts, find allele frequencies p = (2·AA + Aa)/(2N). (3) Given observed vs expected, use chi-square (df = 1) to judge equilibrium. (4) Say which condition is violated when allele frequencies change.']),
 [('Which is NOT a condition for Hardy–Weinberg equilibrium?',['natural selection acting on the gene','random mating','very large population','no gene flow'],0,'The condition is the absence of selection; selection acting on the gene violates it.')])

mod('drift','Genetic drift & gene flow',
 'In small populations, chance alone can change allele frequencies, and it can even remove an allele altogether.',
 ['<b>Genetic drift</b> is random change in allele frequencies from one generation to the next, because a small sample of alleles is passed on. The smaller the population, the larger the effect; in a small population an allele can be lost or <b>fixed</b> (reach 100%) by chance within a few generations. Drift reduces genetic variation and does not favor adaptive alleles.',
  'Two common cases: the <b>bottleneck effect</b> (a disaster leaves only a few survivors, and the survivors\' alleles are not representative; for example northern elephant seals) and the <b>founder effect</b> (a few individuals start a new population with a non-random sample of alleles). <b>Gene flow</b> (migration of alleles between populations) makes populations more similar. Mutation adds new variation; selection, drift, gene flow and mutation together drive evolution.'],
 ('all evolution was adaptive','that chance can change allele frequencies, especially in small populations','why bottlenecked species lose variation and why small populations can fix harmful alleles','drift, bottleneck, founder effect, gene flow'),
 [('drift: random change in allele frequency','strongest in small populations'),('bottleneck: population crash → sample of alleles','loss of variation'),('founder effect: small group starts a new population','non-random sample'),('gene flow: movement of alleles between populations','homogenizes populations')],
 [lab('gd-lab','Allele frequency in small populations',canvas='gd-canvas',aria='Lines showing the frequency of an allele over 60 generations in ten replicate populations of the chosen size.',
   ctl=[('gd-n','Population size',5,500,5,20),('gd-p','Starting allele frequency',.1,.9,.05,.5)],
   pre='<div class="row"><button type="button" class="btn primary" id="gd-run">Run again</button></div>',
   out=[('gd-fix','populations that fixed the allele','x'),('gd-lost','populations that lost the allele','a'),('gd-mid','still variable','v')],own=True),
  lab('gd-lab2','A bottleneck',canvas='gd-canvas2',aria='A population of 100 individuals, 60% blue and 40% pink, before and after a bottleneck leaves only a few survivors who then repopulate.',
   ctl=[('gd-s','Survivors of the bottleneck',2,60,1,6)],
   pre='<div class="row"><button type="button" class="btn primary" id="gd-go">Bottleneck!</button></div>',
   out=[('gd-b','blue before','x'),('gd-a','blue after','a'),('gd-msg','what happened','')],own=True)],
 [('Run with population size 10. What usually happens? <button type="button" class="btn link" data-show=\'' + show(["#gd-n",10],["#gd-p",.5],["click","#gd-run"]) + '\'>Set it up for me</button>','','Several lines hit 0 or 1 (loss or fixation) within the 60 generations: chance dominates.'),
  ('Now use size 500. <button type="button" class="btn link" data-show=\'' + show(["#gd-n",500],["click","#gd-run"]) + '\'>Set it up for me</button>','','The lines wander only slightly: large populations are much less affected by drift.')],
 ('A population of 10,000 beetles is 50% green and 50% brown (neutral trait). A flood leaves 10 survivors, 8 green and 2 brown, and the population regrows. Predict the allele frequencies and name the process.',[
  '<b>After the bottleneck.</b> 8/10 = 80% green, 20% brown (if the trait is a single gene with simple alleles, roughly).',
  '<b>Process.</b> A bottleneck effect: genetic drift in a very small sample.',
  '<b>Consequence.</b> The regrown population is mostly green even though green was no better, and overall genetic variation is lower.']),
 ['Saying drift is a response to the environment.','Saying drift is strong in large populations.','Mixing up bottleneck (a population shrinks) and founder effect (a few individuals start a new population).','Thinking drift always increases fitness.','Forgetting that gene flow brings alleles into a population.'],
 ('Which force is it?',['Ask: Is the change random and size-dependent? Drift. Does it favor traits that raise reproduction? Selection. Are individuals moving between populations? Gene flow. Are new alleles appearing? Mutation.']),
 [('A new island population is started by a few individuals carrying a rare allele. The allele becomes common. This is an example of',['the founder effect','gene flow','stabilizing selection','mutation'],0,'A small founding group carries a non-random sample of alleles.')])

mod('speciation','Speciation & reproductive isolation',
 'A species is a group whose members can interbreed and produce fertile offspring. Species form when groups stop exchanging genes.',
 ['Under the <b>biological species concept</b>, species are populations that can interbreed in nature and produce <b>viable, fertile</b> offspring and are reproductively isolated from other groups. Isolation can be <b>prezygotic</b> (before a zygote forms): habitat, temporal (breeding times), behavioral (courtship), mechanical (structures do not fit), gametic (sperm and egg incompatible). Or <b>postzygotic</b> (after): reduced hybrid viability, reduced hybrid fertility (mule), hybrid breakdown (later generations weak).',
  'In <b>allopatric</b> speciation a geographic barrier splits a population; each side diverges by selection, drift and mutation until they cannot interbreed. In <b>sympatric</b> speciation new species form in the same area, for example by <b>polyploidy</b> in plants or by strong disruptive selection with mating preferences. <b>Adaptive radiation</b> is rapid diversification from an ancestor into many species filling different niches (Darwin\'s finches). Where two groups meet, <b>hybrid zones</b> show how complete isolation is.'],
 ('species were fixed categories','that reproductive isolation separates gene pools and lets groups evolve separately','how a barrier or a mating preference can produce new species','prezygotic and postzygotic barriers, allopatric and sympatric speciation'),
 [('prezygotic: before fertilization','postzygotic: after'),('allopatric: geographic barrier','sympatric: no barrier'),('polyploidy: instant speciation in plants','extra chromosome sets'),('adaptive radiation: one ancestor → many niches','Galápagos finches')],
 [stagelab('sp-lab','Allopatric speciation',canvas='sp-canvas',aria='A population is split by a barrier, the two groups diverge, and when they meet again they cannot interbreed.',p='sp',n=4),
  lab('sp-lab2','Which barrier is it?',canvas='sp-canvas2',aria='A timeline of events from mating to fertile offspring with the stage where reproduction fails marked.',
   seg=('sp-case','Case',[('hab','two frog species breed in different ponds'),('tmp','two skunk species mate in different seasons'),('beh','fireflies use different flash patterns'),('gam','sea urchin sperm cannot fuse with other species\' eggs'),('via','hybrid embryos die early'),('fer','mule (horse × donkey) is sterile')]),
   out=[('sp-kind','barrier','x'),('sp-wh','stage that fails','a'),('sp-ex','explanation','')],own=True)],
 [('Go to the stage where the groups meet again. Why can\'t they interbreed? <button type="button" class="btn link" data-show=\'' + show(["#sp-st",3]) + '\'>Set it up for me</button>','','Changes that built up in isolation (mating signals, timing, chromosome differences) now keep them from producing fertile offspring.'),
  ('Choose "mule". Is this a prezygotic or postzygotic barrier? <button type="button" class="btn link" data-show=\'' + show(["click","#sp-case [data-k=fer]"]) + '\'>Set it up for me</button>','','Postzygotic: horses and donkeys can mate and a hybrid forms, but the hybrid is sterile.')],
 ('Two species of orchids live together and share pollinators. One flowers in May and the other in July, so no hybrids form. Classify the isolation and say what kind of speciation might have produced it.',[
  '<b>Barrier.</b> Different flowering times: temporal isolation, a prezygotic barrier.',
  '<b>Speciation.</b> They share a habitat, so sympatric speciation is plausible (a shift in flowering time creating reproductive isolation).',
  '<b>Evidence.</b> Hybrid formation is prevented before fertilization, so gene flow between them is very low.']),
 ['Calling a mule\'s sterility prezygotic.','Saying speciation needs a physical barrier.','Thinking species form within a single organism\'s lifetime.','Thinking all species concepts give the same answer (asexual organisms and fossils need other concepts).','Confusing polyploidy (extra sets of chromosomes) with aneuploidy.'],
 ('Classification checklist',['Ask: does it block mating or fertilization (prezygotic), or does a zygote form but the hybrid fail (postzygotic)? Then ask if populations were apart (allopatric) or together (sympatric).']),
 [('Horses and donkeys can produce mules, but mules are sterile. This is an example of',['postzygotic isolation','prezygotic isolation','allopatric speciation','temporal isolation'],0,'The hybrid forms but cannot reproduce: reduced hybrid fertility.')])

mod('phylo','Phylogeny & cladograms',
 'A tree of life shows how groups are related, based on shared ancestors and the traits they inherited from them.',
 ['A <b>phylogenetic tree</b> or <b>cladogram</b> shows evolutionary relationships. Each <b>node</b> is a common ancestor; the tips are groups of organisms. A <b>clade</b> (monophyletic group) includes an ancestor and <b>all</b> of its descendants. <b>Sister taxa</b> share the most recent common ancestor. Groups that exclude some descendants (like "reptiles" without birds) are not clades. Position along the tree is about branching order, not about which species is "more advanced".',
  'Trees are built from <b>shared derived characters</b> (traits that appeared in a common ancestor and are inherited by its descendants) and from <b>molecular data</b>: the more differences in DNA or protein sequences, the longer ago two lineages diverged (a <b>molecular clock</b>). <b>Homologous</b> structures share ancestry (a bat wing and human arm); <b>analogous</b> structures evolved independently for similar functions (bird and insect wings) and do not show relatedness. <b>Parsimony</b> prefers the tree needing the fewest evolutionary changes.'],
 ('similar organisms must be closely related','that relatedness is shown by shared ancestry, not by similarity of appearance alone','how to read and build trees from data','nodes, clades, shared derived traits and molecular clocks'),
 [('clade = ancestor + all descendants','monophyletic'),('shared derived trait → groups taxa','in a cladogram'),('homologous: same ancestry; analogous: same function','convergent evolution'),('more sequence differences → older split','molecular clock')],
 [lab('ph2-lab','Read a cladogram',canvas='ph2-canvas',aria='A cladogram of five animals with traits marked on branches and one clade highlighted.',
   seg=('ph2-cl','Highlight clade',[('vert','vertebrates'),('jaw','jawed vertebrates'),('tet','tetrapods'),('amn','amniotes'),('par','frog + mouse')]),
   out=[('ph2-mem','members','x'),('ph2-def','defined by the shared derived trait','a'),('ph2-note','note','')],own=True),
  lab('ph2-lab2','A molecular clock',canvas='ph2-canvas2',aria='A graph of sequence difference against time since divergence for the chosen rate of change.',
   ctl=[('ph2-d','Sequence difference between two species (%)',0,30,.5,6),('ph2-r','Rate of change per lineage (% per million years)',.1,2,.05,.5)],
   out=[('ph2-t','estimated time since the species split','x')],own=True)],
 [('Highlight "amniotes". Which animals are included and what trait defines them? <button type="button" class="btn link" data-show=\'' + show(["click","#ph2-cl [data-k=amn]"]) + '\'>Set it up for me</button>','','Lizard and mouse (the groups that descend from the first animal with the amniotic egg).'),
  ('Set the difference to 6% and the rate to 0.5% per million years per lineage. <button type="button" class="btn link" data-show=\'' + show(["#ph2-d",6],["#ph2-r",.5]) + '\'>Set it up for me</button>','','Both lineages accumulate changes, so t = d/(2r) = 6/(2 × 0.5) = 6 million years (a simplified model).')],
 ('In a cladogram, lizards and birds share a more recent common ancestor with each other than either does with mice. Which two are sister taxa? Is "lizards + mice" a clade?',[
  '<b>Sister taxa.</b> Lizards and birds (they share a node not shared with mice).',
  '<b>Lizards + mice.</b> Their common ancestor also gave rise to birds, so a group of "lizards + mice" excludes some descendants.',
  '<b>Conclusion.</b> It is not a clade (it is paraphyletic).']),
 ['Reading a tree as a ladder with "advanced" species on the right.','Saying analogous structures show close relationships.','Counting all shared traits instead of shared derived traits.','Forgetting that a clade must include all descendants.','Thinking a node represents a living species.'],
 ('Tree reading skills',['Trace back from the tips to the nearest node to find sister groups. To identify a clade, find a node and take everything above it. Use the data (traits or sequences) to decide which taxa share a more recent common ancestor.']),
 [('Which of these is a clade?',['an ancestor and all of its descendants','an ancestor and some descendants','species with the same habitat','organisms with similar appearance'],0,'A clade is monophyletic: it contains the ancestor and every descendant.')])

mod('originlife','Origin of life & evidence from the past',
 'Life on Earth began almost 4 billion years ago, from chemistry that did not need life to start.',
 ['The early Earth (about 4.6 billion years ago) had little or no free oxygen and was bombarded with energy. In the Miller–Urey experiment (1953), a mixture of water vapor, methane, ammonia and hydrogen exposed to sparks produced <b>amino acids</b>, showing that organic molecules can form abiotically. Hypotheses: the <b>RNA world</b> (RNA can store information and act as a catalyst, so it may have come before DNA and proteins) and <b>protocells</b> (lipid vesicles with simple metabolism that could grow and divide). The oldest evidence of life is about 3.5 billion years old (stromatolites: layered rocks made by prokaryotes).',
  'Photosynthetic cyanobacteria raised oxygen in the atmosphere about 2.4 billion years ago, which changed Earth\'s chemistry and living things. Eukaryotes appear about 2 billion years ago (endosymbiosis), multicellular organisms later, and most animal groups in the Cambrian about 540 million years ago. We know the timeline from <b>fossils</b> and <b>radiometric dating</b>: radioactive isotopes decay at a constant <b>half-life</b>, so the fraction remaining gives the age. Age = (number of half-lives) × (half-life).'],
 ('life had always been around, or was a miracle','that simple chemistry can make the building blocks, and that evidence dates the steps','how scientists date fossils and rocks and what the timeline looks like','Miller–Urey, RNA world, protocells and radiometric dating'),
 [('remaining = (½)ⁿ, n = number of half-lives','radioactive decay'),('age = n × half-life','radiometric dating'),('carbon-14 half-life = 5,730 years','up to about 50,000 years'),('uranium-238 half-life ≈ 4.5 billion years','dates old rocks')],
 [lab('ol-lab','Radiometric dating',canvas='ol-canvas',aria='A decay curve showing the fraction of the isotope remaining against time, with the chosen fraction marked.',
   seg=('ol-iso','Isotope',[('c14','carbon-14 (5,730 yr)'),('k40','potassium-40 (1.25 billion yr)'),('u238','uranium-238 (4.47 billion yr)')]),
   ctl=[('ol-f','Percent of the isotope remaining',1,100,1,25)],
   out=[('ol-n','half-lives elapsed','x'),('ol-age','age of the sample','a'),('ol-use','good for dating','')],own=True),
  lab('ol-lab2','Timeline of life',canvas='ol-canvas2',aria='A timeline of Earth\'s history with the chosen time marked and the events that have occurred so far.',
   ctl=[('ol-t','Billions of years ago',0,4.6,.1,3.5)],
   out=[('ol-ev','what has happened by then','x'),('ol-life','life at that time','a')],own=True)],
 [('Set 25% remaining for carbon-14. How old is the sample? <button type="button" class="btn link" data-show=\'' + show(["click","#ol-iso [data-k=c14]"],["#ol-f",25]) + '\'>Set it up for me</button>','','25% = (½)², so 2 half-lives = 11,460 years.'),
  ('Switch to uranium-238 at 50%. What age? <button type="button" class="btn link" data-show=\'' + show(["click","#ol-iso [data-k=u238]"],["#ol-f",50]) + '\'>Set it up for me</button>','','One half-life, about 4.47 billion years: uranium dates very old rocks, not recent fossils.'),
  ('Set the timeline to 2.4 billion years ago. <button type="button" class="btn link" data-show=\'' + show(["#ol-t",2.4]) + '\'>Set it up for me</button>','','Photosynthetic cyanobacteria are raising atmospheric oxygen; life is still single-celled.')],
 ('A fossil contains 12.5% of its original carbon-14. (Half-life 5,730 years.) How old is it?',[
  '<b>Fraction.</b> 12.5% = 1/8 = (½)³.',
  '<b>Half-lives.</b> 3 half-lives have passed.',
  '<b>Age.</b> 3 × 5,730 = 17,190 years.']),
 ['Using carbon-14 for rocks millions of years old (too little remains).','Mixing up the number of half-lives and the age.','Saying Miller–Urey made life (it made amino acids).','Saying the RNA world is proven (it is a hypothesis with supporting evidence).','Putting eukaryotes before the first prokaryotes.'],
 ('Reading evidence',['Answers should connect the evidence to the claim: fossils and radiometric dates give timing; Miller–Urey shows monomers can form; ribozymes support an RNA world; shared genes and the universal code support common ancestry.']),
 [('A sample has 25% of its radioactive isotope left. How many half-lives have passed?',['2','4','1','25'],0,'25% = (½)², so 2 half-lives.')])
